/* === 隐藏头像并修复时间戳位置 === */
/* 1. 隐藏头像（可点心声） */
.message-bubble .avatar {
  opacity: 0 !important;
}
/* 2. 移除消息容器原本为头像留出的间距 */
.message-wrapper {
  gap: 0 !important;
}
/* 3. 使用 transform 将气泡向外平移 */
.message-bubble.ai {
  transform: translateX(-42px) !important;
}
.message-bubble.user {
  transform: translateX(42px) !important;
}
/* 4. [修复] 调整时间戳的绝对位置以对齐移动后的气泡 (不再使用 transform, 避免冲突) */
.message-wrapper.ai .timestamp {
  left: 8px !important; /* 原 left: 50px, 气泡左移 42px -> 50-42=8 */
  bottom:-17px;
  transform: none !important; /* 确保没有其他 transform 影响 */
}
.message-wrapper.user .timestamp {
  right: 8px !important; /* 原 right: 50px, 气泡右移 42px -> 50-42=8 */
  bottom:-17px;
  transform: none !important; /* 确保没有其他 transform 影响 */
}
/* 5. [保留] 调整贴纸位置 */
/* 这个 ::after 是 .message-bubble 的子元素, 会自动跟随第3步的气泡位移, 这里只是微调 */
.message-bubble.ai::after {
  /* --- 您可以调节这里 --- */
  /* 新增 translateY() 来控制上下平移。正数向下，负数向上。*/  transform: translateY(9px) !important;
  /* 这是贴纸的基础垂直位置，也可以调节 */
  bottom: 7px !important;
  /* -------------------------- */
  top: auto !important;
}
.message-bubble.user::after {
  /* --- 您可以调节这里 --- */
  /* 新增 translateY() 来控制上下平移。正数向下，负数向上。*/
  transform: translateY(9px) !important;
  /* 这是贴纸的基础垂直位置，也可以调节 */
  bottom: 8px !important;
  /* -------------------------- */
  top: auto !important;
}
