/* =================================================================== */
/* A. 全局样式&主题定义                                              */
/* =================================================================== */

:root { 
  /* -- 蓝白灰色系调色板 -- */
  --accent-color: #0191fd;      /* 主题强调色 (蓝色) */
  --secondary-bg: #e9e9eb;      /* 次要背景/对方气泡/顶栏 (浅灰色) */
  --border-color: #dcdcdc;      /* 边框和分割线 (比浅灰更深的灰色) */
  --text-primary: #333333;      /* 主要文字颜色 (深灰色/接近黑) */
  --text-secondary: #888888;    /* 次要文字/时间戳 (中灰色) */
}

@keyframes spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

/* =================================================================== */
/* B. 顶部与底部栏                                                     */
/* ================================================================== */
/* 1. 聊天页面总背景 (所有气泡后面的那一层) */
#chat-interface-screen {
  background-color:#ffffff
!important;
}
/* --- 顶部栏 --- */
#chat-interface-screen .header {
  position: relative !important;
  background-image: none !important;
  background-color:#f7f7f7 !important;
  border-bottom: 1px solid var(--border-color) !important;
  min-height: 70px !important;/* 顶栏的高度调这里                                        */
}
/* 在这里换顶栏头像！图片链接！                                              */
#chat-interface-screen .header::before {
  content: '';
  position: absolute;
  display: block;
  left: 50%;
  top: 55%;/* 顶栏头像位置可调                                     */
  transform: translate(-50%, -50%);
  border-radius: 50%;
  background-image: url('https://i.postimg.cc/DfcW334J/IMG-20251022-191324.png');/* 换头像在这里！                                              */
  width: 45px;
  height: 45px;/* 顶栏头像的大小调宽高                                             */
  background-size: cover;
  background-position: center;
}

#chat-header-title-wrapper {
  display: block !important;
  position: absolute !important;
  width: 100% !important;
  left: 50%;
  transform: translateX(-50%) !important;
  text-align: center !important;
  top: 75% !important;/* 备注的上下位置调整                                             */ 
  bottom: auto !important;
  align-items: center !important;
}

#chat-header-title-wrapper #chat-header-title {
  position: static !important;
  transform: none !important;
  text-align: center !important;
  color: var(--text-primary) !important;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif !important;
  font-size: 14px !important; 
}

/* --- 正在输入状态 --- */
#chat-header-status { display: none !important; }

#chat-interface-screen .header #chat-header-title.typing-status {
  color: transparent !important;
  position: relative !important;
}
#chat-interface-screen .header #chat-header-title.typing-status::before {
  content: "对方正在输入";
  font-size: 14px !important;
  color: var(--text-secondary);
  font-style: italic;
  font-weight: 500;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif !important;
  position: absolute;
  top: 0;
  white-space: nowrap;
  left: 36%;
  transform: translateX(-40%);
}
/* 兔版本隐藏掉原来的心跳按钮 */
#char-heart-btn {
opacity: 0 !important;
}
/* 330隐藏记忆 */
